const spellState = new WeakMap<Document, SpellState>();

export function attachSpellCheck(doc: Document, dict: Set<string>): Document {
  spellState.set(doc, { dictionary: dict });
  return doc;
}
export function spellCheck(doc: Document, text: string): string[] | undefined {
  return spellState.get(doc)?.dictionary.check(text);   // absent -> undefined
}
